      /^[A-Z][A-Z0-9_]{0,127}$/.test(p.tokenEnv??'')&&Array.isArray(p.procedures)&&p.procedures.length>0&&
      p.procedures.every(id=>id==='*'||ids.has(id)),'A2A_ANALYSIS_PRINCIPAL_INVALID');
    principals.add(p.name);
  }
