    help:{type:'boolean',short:'h'},url:{type:'string'},directory:{type:'string'},procedure:{type:'string'},
    'parameters-file':{type:'string'},'message-id':{type:'string'},'token-env':{type:'string'},
    task:{type:'string'},'no-wait':{type:'boolean'}
