  return (req,res,next)=>{
    const header=req.headers.authorization;
    const match=typeof header==='string'?/^Bearer ([^\s]+)$/i.exec(header):null;
    if(!match){res.set('WWW-Authenticate','Bearer');res.status(401).json({error:'Authentication required.'});return;}
