      signal:AbortSignal.any([shutdown.signal,AbortSignal.timeout(30000),...(signal?[signal]:[])])};
    if(body!==undefined){
      const raw=encoded(body);need(raw.length<=256*1024,'MCP_COLLECTION_RECOVERY_REQUEST_TOO_LARGE');
