  need(projected.every(name=>columns.has(name)),'MCP_DATASET_UNKNOWN_FIELD');
  const limit=Number(params.get('limit')??value.defaultLimit);
  need(limit<=value.maxLimit,'MCP_DATASET_PAGE_LIMIT_EXCEEDS_DESCRIPTION');
