    row.started.intentId===row.intentId&&row.started.configSha256===row.config.sha256&&
    typeof row.started.at==='string'&&Number.isFinite(Date.parse(row.started.at)),
    'RUNBOOK_ACCOUNTING_ORIGINAL_ATTEMPT_REQUIRED');
