    bodySha256:row.body?.sha256??null,bodyBytes:row.body?.bytes??0,evidencePath,
    recordAuthority:'ORIGINAL_SF36_LEDGER; THIS_FILE_IS_A_SAVED_ACQUISITION_VIEW'};
