  }
  async function ready(id) {
    const result=await optional(join(root(id),'ready.json'));
    if(result){
      check(result.schema===SCHEMA&&result.id===id&&result.configPath===join(configsDirectory,configuration(id))&&
        result.configName===configuration(id)&&/^[a-f0-9]{64}$/.test(result.configSha256),
        'REQUEST_READY_BINDING_CHANGED');
      const review=await reviewRecord(id,result.reviewRevision);
      const attempt=attemptRecord(id,result.generation,await json(join(root(id),'attempts','a'+result.generation+'.json')));
      check(attempt.reviewSha256===review.reviewSha256&&result.reviewSha256===review.reviewSha256&&
        result.operatorDirectory===attempt.operatorDirectory,'REQUEST_READY_BINDING_CHANGED',409);
    }
    return result;
  }
  async function get(id) {
    const item=await verifiedSource(id);
    const view=await inspectOperationHandoff({file:source(id),directory:join(root(id),'review-input'),requireCurrent:false});
    const [review,prepared]=await Promise.all([reviews(id),ready(id)]);
    return {...item,view,review,prepared,preparing:!prepared&&Boolean(await attemptForReview(id,review)),
      expired:view.operationTicket!==null&&view.operationTicket.expiresAt<=Date.now()};
  }
  async function receive(input) {
    fields(input,['filename','base64']);
    check(typeof input.filename==='string'&&input.filename.length>=1&&input.filename.length<=180&&
      !/[\x00-\x1f\x7f]/.test(input.filename),'REQUEST_FILENAME_INVALID');
    check(typeof input.base64==='string'&&input.base64.length<=4*Math.ceil(OPERATION_HANDOFF_MAX_BYTES/3),
      'REQUEST_FILE_TOO_LARGE',413);
    const raw=Buffer.from(input.base64,'base64');
    check(raw.length>0&&raw.length<=OPERATION_HANDOFF_MAX_BYTES&&raw.toString('base64')===input.base64,
      'REQUEST_FILE_ENCODING_INVALID');
    const id='request-'+hash(raw),path=root(id);
    await privateDirectory(path,true);await privateDirectory(join(path,'reviews'),true);
    await privateDirectory(join(path,'attempts'),true);
    await publish(source(id),raw,{same:true,raw:true});
    const existing=await optional(join(path,'request.json'));
    if(existing)return get(id);
    const view=await inspectOperationHandoff({file:source(id),directory:join(path,'review-input')});
    await publish(join(path,'request.json'),{schema:SCHEMA,id,filename:basename(input.filename),createdAt:new Date().toISOString(),
      handoffSha256:hash(raw),summary:{intentId:view.intentId,url:view.sellerUrl,method:view.method,bodyBytes:view.bodyBytes,
        bodySha256:view.bodySha256,expiresAt:view.operationTicket?.expiresAt??null}});
    return get(id);
  }
  async function review(input) {
    fields(input,['id','acceptIndex','totalAtomic','dailyAtomic']);
    const item=await verifiedSource(input.id),operator=await preset();
    check(!await ready(input.id),'REQUEST_ALREADY_PREPARED',409);
    check(Number.isSafeInteger(input.acceptIndex)&&input.acceptIndex>=0,'EXPLICIT_SELECTION_INDEX_REQUIRED');
    const view=await inspectOperationHandoff({file:source(input.id),directory:join(root(input.id),'review-input'),
      acceptIndex:input.acceptIndex});
    const total=amount(input.totalAtomic),daily=amount(input.dailyAtomic),single=BigInt(view.acceptedTerms.maxAtomic);
    check(single<=BigInt(daily)&&BigInt(daily)<=BigInt(total)&&BigInt(total)<=BigInt(operator.value.maxTotalAtomic)&&
      BigInt(daily)<=BigInt(operator.value.maxDailyAtomic),'REQUEST_BUDGET_OUTSIDE_OPERATOR_LIMITS');
    const proof={schema:SCHEMA,id:input.id,handoffSha256:item.handoffSha256,acceptIndex:input.acceptIndex,
      acceptedTerms:view.acceptedTerms,bodySha256:view.bodySha256,requestHeaders:view.requestHeaders,
      operationKey:view.operationTicket?.operationKey??null,requestHash:view.operationTicket?.requestHash??null,
      operationTicketSha256:view.operationTicket?.sha256??null,
      settingsSha256:operator.sha256,operator:operator.view,totalAtomic:total,dailyAtomic:daily};
    const old=await reviews(input.id),result={...proof,reviewSha256:hash(encode(proof)),
      revision:(old?.revision??0)+1,reviewedAt:new Date().toISOString()};
    check(result.revision<=10000,'REQUEST_REVIEW_LIMIT');
    await publish(join(root(input.id),'reviews','r'+result.revision+'.json'),result);
    return {...await get(input.id),review:result};
  }
  async function verifyOperator(attempt,review,settings) {
    const result=await openWorkspace(['--dir',attempt.operatorDirectory]);
    const cfg=result.config,op=cfg.operation,manifest=result.manifest;
    const item=await record(review.id);
    const sourceView=await inspectOperationHandoff({file:source(review.id),directory:attempt.inputDirectory,acceptIndex:review.acceptIndex});
    const bodyPresent=sourceView.bodyPresent;
    check(op.method===sourceView.method&&op.url===item.summary.url&&JSON.stringify(op.expect)===JSON.stringify(review.acceptedTerms)&&
      op.intentId===item.summary.intentId&&
      JSON.stringify(op.headers)===JSON.stringify(review.requestHeaders)&&cfg.trustedPayer===settings.payer&&
      cfg.operator.actor===settings.actor&&cfg.operator.service===settings.service&&cfg.operator.python===settings.python&&
      op.bodyFile===(bodyPresent?join(attempt.inputDirectory,'request.body'):undefined)&&op.ticketFile===(sourceView.operationTicket?join(attempt.operatorDirectory,'operation-ticket.json'):undefined),
      'REQUEST_OPERATOR_BINDING_CHANGED',409);
    check(manifest.signer.secretEnv===(settings.signerProvider===undefined?settings.secretEnv??'STELLAR_SECRET':undefined)&&
      manifest.signer.signerProvider===settings.signerProvider,'REQUEST_SIGNER_BINDING_CHANGED',409);
    const expectedPins=validateNativeSignerConfiguration({...review.acceptedTerms,expectedPayer:settings.payer,rpcUrl:settings.rpc});
    check(manifest.signer.rpcUrl===expectedPins.rpcUrl&&manifest.signer.maxAtomic===review.acceptedTerms.maxAtomic,
      'REQUEST_SIGNER_BINDING_CHANGED',409);
    const expectedTransport=buyerTransport({operation:op,...(settings.httpsProxyEnv===undefined?{}:
      {buyerTransport:{mode:'explicit-connect',origin:new URL(op.url).origin,proxyEnv:settings.httpsProxyEnv}})});
    check(JSON.stringify(buyerTransport(cfg))===JSON.stringify(expectedTransport),'REQUEST_TRANSPORT_BINDING_CHANGED',409);
    const ticket=await loadOperationTicket(op,{requireCurrent:true});
    check((ticket?.sha256??null)===review.operationTicketSha256&&(ticket?.operationKey??null)===review.operationKey&&
      (ticket?.requestHash??null)===review.requestHash,'REQUEST_TICKET_CHANGED',409);
    check(hash(bodyPresent?await bytes(op.bodyFile,MAX_REQUEST_BODY_BYTES):new Uint8Array())===review.bodySha256,'REQUEST_BODY_CHANGED',409);
    const policy=await json(cfg.operator.policy);
    check(policy.assets?.length===1&&policy.assets[0].max_single===review.acceptedTerms.maxAtomic&&
      policy.assets[0].max_total===review.totalAtomic&&policy.assets[0].max_per_utc_day===review.dailyAtomic,
      'REQUEST_OPERATOR_BUDGET_CHANGED',409);
    return result;
  }
  async function finish(attempt,review,settings) {
    const native=await verifyOperator(attempt,review,settings),raw=await bytes(native.configPath);
    const destination=join(configsDirectory,configuration(review.id));
    await publish(destination,raw,{same:true,raw:true});
    const value={schema:SCHEMA,id:review.id,reviewSha256:review.reviewSha256,configPath:destination,
      configName:configuration(review.id),configSha256:hash(raw),operatorDirectory:attempt.operatorDirectory,
      generation:attempt.generation,reviewRevision:review.revision,intentId:native.config.operation.intentId,createdAt:new Date().toISOString()};
    const old=await ready(review.id);
    if(old){check(old.configSha256===value.configSha256&&old.operatorDirectory===value.operatorDirectory,
      'REQUEST_READY_BINDING_CHANGED',409);return old;}
    await publish(join(root(review.id),'ready.json'),value);return value;
  }
  async function prepareAttempt(attempt,selected,value) {
    await importOperationHandoff({file:source(attempt.id),directory:attempt.inputDirectory,acceptIndex:selected.acceptIndex,resume:true});
    const args=['--config',join(attempt.inputDirectory,'review.json'),'--dir',attempt.operatorDirectory,
      '--actor',value.actor,'--service',value.service,'--payer',value.payer,'--python',value.python,
      '--total-atomic',selected.totalAtomic,'--daily-atomic',selected.dailyAtomic];
    for(const [key,flag]of [['secretEnv','--secret-env'],['signerProvider','--signer-provider'],['rpc','--rpc'],['httpsProxyEnv','--https-proxy-env']])
      if(value[key]!==undefined)args.push(flag,value[key]);
    await initializeWorkspace(args,{resume:true});
    return finish(attempt,selected,value);
  }
  async function provision(input) {
    fields(input,['id','reviewSha256']);
    const item=await verifiedSource(input.id),existing=await ready(input.id);
    if(existing){check(existing.reviewSha256===input.reviewSha256,'REQUEST_ALREADY_PREPARED',409);return existing;}
    const selected=await reviews(input.id);
    check(selected&&selected.reviewSha256===input.reviewSha256,'REQUEST_REVIEW_CHANGED',409);
    const retainedAttempt=await attemptForReview(input.id,selected);
    const operator=retainedAttempt?await attemptPreset(retainedAttempt,selected):await preset();
    check(selected.settingsSha256===operator.sha256,'REQUEST_OPERATOR_SETTINGS_CHANGED',409);
    const current=await inspectOperationHandoff({file:source(input.id),directory:join(root(input.id),'review-input'),acceptIndex:selected.acceptIndex});
    check(JSON.stringify(selected.acceptedTerms)===JSON.stringify(current.acceptedTerms)&&
      selected.bodySha256===current.bodySha256&&selected.operationTicketSha256===(current.operationTicket?.sha256??null)&&
      JSON.stringify(selected.requestHeaders)===JSON.stringify(current.requestHeaders)&&
      JSON.stringify(selected.operator)===JSON.stringify(operator.view),'REQUEST_REVIEW_CHANGED',409);
    const intentPath=join(directory,'intents',hash(item.summary.intentId)+'.json');
    await publish(intentPath,{id:input.id,intentId:item.summary.intentId},{same:true});
    const attemptsDirectory=join(root(input.id),'attempts');
    const names=(await readdir(attemptsDirectory)).filter(name=>/^a[1-9][0-9]*\.json$/.test(name))
      .sort((a,b)=>Number(b.slice(1,-5))-Number(a.slice(1,-5)));
    if(retainedAttempt) {
      // Resume the original generation with its retained complete settings even
      // when a later host selection is active. Its native keys/ledger stay owned
      // by the same importer and initializer.
      const manifest=await optional(join(retainedAttempt.operatorDirectory,'workspace.json'));
      if(manifest)return finish(retainedAttempt,selected,operator.value);
      return prepareAttempt(retainedAttempt,selected,operator.value);
    }
    const generation=names.length?Number(names[0].slice(1,-5))+1:1;
    check(Number.isSafeInteger(generation)&&generation<=10000,'REQUEST_ATTEMPT_LIMIT');
    const attempt={schema:SCHEMA,id:input.id,generation,reviewSha256:selected.reviewSha256,
      inputDirectory:join(root(input.id),'input-'+generation),operatorDirectory:join(root(input.id),'operator-'+generation)};
    await publish(attemptSettingsPath(attempt),operator.raw,{same:true,raw:true});
    await publish(join(attemptsDirectory,'a'+generation+'.json'),attempt);
    return prepareAttempt(attempt,selected,operator.value);
  }
  async function state() {
    const requests=[],errors=[],operatorSetupState=await operatorSetup.state();
    const operator=operatorSetupState.operator,presetError=operatorSetupState.error,settingsFile=operatorSetupState.settingsFile;
    for(const id of (await readdir(directory)).filter(name=>ID.test(name))){
      try{const item=await record(id),review=await reviews(id),prepared=await ready(id);
        requests.push({...item,prepared,preparing:!prepared&&Boolean(await attemptForReview(id,review)),
          reviewSettingsSha256:review?.settingsSha256??null,reviewRevision:review?.revision??null});}
      catch(error){errors.push({id,code:codeOf(error)});}
    }
    requests.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
    const customerClients=await clients.state();
    return {requests,errors:[...errors,...customerClients.errors],operator,presetError,settingsFile,
      operatorSettingsSha256:operatorSetupState.settingsSha256,operatorSetup:operatorSetupState,
      maxHandoffBytes:OPERATION_HANDOFF_MAX_BYTES,clients:customerClients};
  }
  async function originalOperatorForOperation(op,accounting=false) {
    const path=op.sourceConfig?.path;
    if(typeof path!=='string'||dirname(path)!==configsDirectory||!/^received-[a-f0-9]{64}\.json$/.test(basename(path)))return null;
    const id='request-'+basename(path).slice(9,-5),saved=await ready(id);
    check(saved&&saved.configPath===path&&saved.configSha256===op.sourceConfig.sha256&&
      hash(await bytes(path))===saved.configSha256,'REQUEST_OPERATOR_SETUP_CHANGED',409);
    const native=await openWorkspace(['--dir',saved.operatorDirectory],{accounting});
    check(hash(await bytes(native.configPath))===saved.configSha256,'REQUEST_OPERATOR_SETUP_CHANGED',409);
    return native;
  }
  async function environmentForOperation(op) {
    const native=await originalOperatorForOperation(op,true);
    return native?{...process.env,...native.operatorEnvironment}:process.env;
  }
  async function workspaceForOperation(op) {
    const native=await originalOperatorForOperation(op);
    return native?.manifest.directory??null;
  }
  async function attachment(id,kind) {
    await verifiedSource(id);check(['body','handoff'].includes(kind),'REQUEST_ATTACHMENT_INVALID');
    const raw=kind==='body'?await readOperationHandoffBody({file:source(id)}):await bytes(source(id),OPERATION_HANDOFF_MAX_BYTES);
    check(raw!==null,'REQUEST_BODY_ABSENT',404);
    return {bytes:raw,name:kind==='body'?'request.body':'merchant-operation.handoff.json'};
  }
  const clients=await createSellerClientIntake({directory:join(directory,'clients'),request:get,receiveRequest:receive,
    storage:{privateDirectory,bytes,publish,json,optional,lease,lstat,readdir}});
  return {state,get,attachment,environmentForOperation,workspaceForOperation,clients,operatorSetup,
    receive:input=>lease(()=>receive(input)),review:input=>lease(()=>review(input)),provision:input=>lease(()=>provision(input))};
}

// MIT. Versioned host settings for the original buyer intake and native operator.
import {constants} from 'node:fs';
import {access,open,rename,unlink} from 'node:fs/promises';
import {createHash,randomUUID} from 'node:crypto';
import {join} from 'node:path';
import {isDeepStrictEqual} from 'node:util';

const REVISION='stellar-forge.buyer-operator-preset-revision.v1';
const SELECTION='stellar-forge.buyer-operator-preset-selection.v1';
const REVIEW='stellar-forge.buyer-operator-preset-review.v1';
const ID=/^preset-[a-f0-9]{64}$/,SHA=/^[a-f0-9]{64}$/;
const KEYS=['schema','actor','service','payer','python','maxTotalAtomic','maxDailyAtomic',
  'secretEnv','signerProvider','rpc','httpsProxyEnv'];
const hash=raw=>createHash('sha256').update(raw).digest('hex');
const encode=value=>Buffer.from(JSON.stringify(value,null,2)+'\n');
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const check=(ok,code,status=422)=>{if(!ok)throw Object.assign(new Error(code),{code,status});};
const codeOf=error=>/^[A-Z0-9_]{1,120}$/.test(error?.code??'')?error.code:'OPERATOR_SETTINGS_UNAVAILABLE';
function canonicalSettings(value) {
  const result=Object.fromEntries(KEYS.filter(key=>Object.hasOwn(value,key)).map(key=>[key,value[key]]));
  // This is the original native default. An explicit default in the form can
  // adopt a launcher preset that omitted it without changing the preset bytes.
  if(result.signerProvider===undefined&&result.secretEnv===undefined)result.secretEnv='STELLAR_SECRET';
  return result;
}

/** One host selection, under the same lease as original request preparation. */
export async function openBuyerOperatorSetup({directory,declaredSettingsFile,readPreset,validatePreset,storage}) {
  const {privateDirectory,bytes,publish,json,optional,readdir,lease}=storage;
  const root=join(directory,'operator-presets'),records=join(root,'revisions'),selectionFile=join(root,'current.json');
  await privateDirectory(root,true);await privateDirectory(records,true);
  function paths(id) {
    check(typeof id==='string'&&ID.test(id),'OPERATOR_REVISION_INVALID');
    return {metadata:join(records,id+'.json'),settings:join(records,id+'.settings.json'),
      previous:join(records,id+'.previous.json'),previousSelection:join(records,id+'.previous-selection.json')};
  }
  async function maybeBytes(file,limit=16384) {
    try{return await bytes(file,limit);}catch(error){if(error.code==='ENOENT')return null;throw error;}
  }
  async function record(id) {
    const files=paths(id),item=await json(files.metadata),proof=item.proof;
    check(item.schema===REVISION&&item.id===id&&Number.isSafeInteger(item.revision)&&item.revision>0&&item.revision<=10000&&
      typeof item.createdAt==='string'&&Number.isFinite(Date.parse(item.createdAt))&&object(proof)&&proof.schema===REVIEW&&
      proof.directory===directory&&object(proof.base)&&SHA.test(proof.settingsSha256??'')&&
      typeof proof.note==='string'&&(proof.sourceRevision===null||ID.test(proof.sourceRevision??''))&&
      id==='preset-'+hash(encode(proof)),'OPERATOR_REVISION_CHANGED',409);
    const preset=await readPreset(files.settings);
    check(preset.sha256===proof.settingsSha256,'OPERATOR_REVISION_SETTINGS_CHANGED',409);
    return {...item,preset,files};
  }
  async function snapshot() {
    let selectionRaw=null,raw=null,preset=null,item=null,error=null;
    const base={mode:'NONE',selectionSha256:null,selectedId:null,file:null,settingsSha256:null,error:null};
    try {
      selectionRaw=await maybeBytes(selectionFile);
      if(selectionRaw!==null) {
        base.mode='WORKSPACE';base.selectionSha256=hash(selectionRaw);
        let selection;try{selection=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(selectionRaw));}
        catch{check(false,'OPERATOR_SELECTION_INVALID',409);}
        check(object(selection)&&Object.keys(selection).length===3&&selection.schema===SELECTION&&
          ID.test(selection.id??'')&&SHA.test(selection.settingsSha256??''),'OPERATOR_SELECTION_INVALID',409);
        base.selectedId=selection.id;base.file=paths(selection.id).settings;
        raw=await maybeBytes(base.file);base.settingsSha256=raw===null?null:hash(raw);
        item=await record(selection.id);preset=item.preset;
        check(raw!==null&&hash(raw)===preset.sha256&&selection.settingsSha256===preset.sha256,
          'OPERATOR_SELECTION_SETTINGS_CHANGED',409);
      } else if(declaredSettingsFile!==null) {
        base.mode='DECLARED';base.file=declaredSettingsFile;
        raw=await maybeBytes(declaredSettingsFile);base.settingsSha256=raw===null?null:hash(raw);
        preset=await readPreset(declaredSettingsFile);
        check(raw!==null&&hash(raw)===preset.sha256,'OPERATOR_DECLARED_SETTINGS_CHANGED',409);
      }
    } catch(failure) {error=codeOf(failure);base.error=error;preset=null;}
    return {base,stateSha256:hash(encode(base)),selectionRaw,raw,preset,item,error};
  }
  async function currentFile() {return (await snapshot()).base.file;}
  async function read() {
    const current=await snapshot();
    check(!current.error,current.error??'OPERATOR_SETTINGS_UNAVAILABLE',409);
    check(current.preset,'REQUEST_OPERATOR_PRESET_REQUIRED');
    return {...current.preset,raw:current.raw};
  }
  async function readMatching(settingsSha256) {
    check(typeof settingsSha256==='string'&&SHA.test(settingsSha256),'OPERATOR_SETTINGS_DIGEST_INVALID');
    const current=await snapshot();
    if(current.preset?.sha256===settingsSha256)return {...current.preset,raw:current.raw};
    // Legacy in-progress requests predate attempt-local preset copies. Adopt
    // only actual original preset bytes retained by a host revision/change.
    for(const name of (await readdir(records)).filter(name=>/^preset-[a-f0-9]{64}\.(?:settings|previous)\.json$/.test(name))) {
      try {const file=join(records,name),raw=await bytes(file,16384);
        if(hash(raw)!==settingsSha256)continue;
        const preset=await readPreset(file);
        check(preset.sha256===settingsSha256,'OPERATOR_REVISION_SETTINGS_CHANGED',409);
        return {...preset,raw};
      } catch(error) {if(error.code==='OPERATOR_REVISION_SETTINGS_CHANGED')throw error;}
    }
    check(false,'OPERATOR_RETAINED_SETTINGS_REQUIRED',409);
  }
  async function history(selectedId) {
    const names=(await readdir(records)).filter(name=>/^preset-[a-f0-9]{64}\.json$/.test(name));
    check(names.length<=10000,'OPERATOR_REVISION_LIMIT');
    const result=[];
    for(const name of names) {
      const id=name.slice(0,-5);
      try {const item=await record(id);result.push({id,revision:item.revision,createdAt:item.createdAt,
        actor:item.preset.value.actor,service:item.preset.value.service,note:item.proof.note,
        settingsSha256:item.preset.sha256,current:id===selectedId,sourceRevision:item.proof.sourceRevision});}
      catch(error){result.push({id,error:codeOf(error),current:id===selectedId});}
    }
    return result.sort((a,b)=>(b.revision??0)-(a.revision??0)||a.id.localeCompare(b.id));
  }
  async function availability(value) {
    if(!value)return null;
    const available=async(path,mode)=>{try{await access(path,mode);return true;}catch{return false;}};
    return {python:{path:value.python,available:await available(value.python,constants.X_OK)},
      signer:value.signerProvider!==undefined?
        {kind:'TRUSTED_SEP43_PROVIDER',path:value.signerProvider,available:await available(value.signerProvider,constants.R_OK)}:
        {kind:'ENVIRONMENT',name:value.secretEnv??'STELLAR_SECRET',available:Boolean(process.env[value.secretEnv??'STELLAR_SECRET'])},
      proxy:value.httpsProxyEnv===undefined?null:{name:value.httpsProxyEnv,available:Boolean(process.env[value.httpsProxyEnv])}};
  }
  async function state() {
    const current=await snapshot();
    return {schema:SELECTION,directory,configured:Boolean(current.preset),mode:current.base.mode,
      revision:current.base.selectedId,revisionNumber:current.item?.revision??null,
      stateSha256:current.stateSha256,settingsFile:current.base.file,settingsSha256:current.preset?.sha256??null,
      operator:current.preset?.view??null,settings:current.preset?.value??null,error:current.error,
      defaultPython:'/usr/bin/python3',declaredSettingsFile,history:await history(current.base.selectedId),
      availability:await availability(current.preset?.value)};
  }
  async function inputSettings(input,current,{save=false}={}) {
    const allowed=['settings','expectedStateSha256','note','sourceRevision',...(save?['expectedReviewSha256']:[])];
    check(object(input)&&Object.keys(input).every(key=>allowed.includes(key))&&object(input.settings)&&
      SHA.test(input.expectedStateSha256??'')&&(!save||SHA.test(input.expectedReviewSha256??'')),
      'OPERATOR_SETTINGS_FIELDS_INVALID');
