    ...(c.feeBumpSigner ? [c.feeBumpSigner.address] : [])])].sort();
  if (directory === null) return Object.freeze({
    status:() => ({mode:'PROCESS_LOCAL',state:'ACTIVE',network:c.network,accounts}),
    release:async () => {},
